  1→import { useState } from 'react'
  2→import { ApolloError } from '@apollo/client'
  3→import { message } from 'antd'
  4→import {
  5→    useCreateDictionaryMutation,
  6→    useDeleteDictionariesMutation,
  7→    useUpdateDictionaryMutation,
  8→    type DictionaryFindInput,
  9→    DictionarySortField,
 10→    Direction
 11→} from '@/generated/real-hooks'
 12→import { AUDIT_ACTION } from '@/shared/constants/auditWhatCodes'
 13→import { useOverlay } from '@/shared/libs/OverlayProvider'
 14→import { useUserStore } from '@/shared/stores/useUserStore'
 15→import { getCurrentTime } from '@/shared/utils/format'
 16→import type { DictionaryFormValues, DictionaryItem, DictionarySearchForm } from '@/views/dictionary-manage/model/type'
 17→import { useDictionariesWithUsers } from '../../../shared/services/graphql/dictionary/useDictionariesWithUsers'
 18→import { DictionaryManageFormModal } from '../ui/modal/DictionaryManageFormModal'
 19→
 20→export const useDictionaryManagement = () => {
 21→    const overlay = useOverlay()
 22→    const user = useUserStore((state) => state.user)
 23→
 24→    const [searchConditions, setSearchConditions] = useState<DictionarySearchForm>({})
 25→    const [currentPage, setCurrentPage] = useState<number>(1)
 26→    const [pageSize, setPageSize] = useState<number>(10)
 27→    const [selectedRowKeys, setSelectedRowKeys] = useState<React.Key[]>([])
 28→    const [selectedItem, setSelectedItem] = useState<DictionaryItem | undefined>(undefined)
 29→
 30→    // 검색 조건을 GraphQL input으로 변환
 31→    const buildQueryInput = (): DictionaryFindInput => {
 32→        const input: DictionaryFindInput = {}
 33→
 34→        // 카테고리 ID 직접 필터 (AutoComplete에서 선택한 경우)
 35→        if (searchConditions.categoryIds) {
 36→            input.categoryIds = [...searchConditions.categoryIds]
 37→        }
 38→
 39→        // 키워드 필터 처리
 40→        if (searchConditions.keywordFilter?.option) {
 41→            const { option, word, userId } = searchConditions.keywordFilter
 42→            switch (option) {
 43→                case 'name':
 44→                    if (word) input.name = word
 45→                    break
 46→                case 'number':
 47→                    if (word) input.id = Number(word)
 48→                    break
 49→                case 'author':
 50→                    // userId가 있으면 userId 사용 (사용자 선택), 없으면 word 사용 (직접 입력)
 51→                    if (userId) input.createdBy = userId
 52→                    else if (word) input.createdBy = word
 53→                    break
 54→                case 'modifier':
 55→                    // userId가 있으면 userId 사용 (사용자 선택), 없으면 word 사용 (직접 입력)
 56→                    if (userId) input.updatedBy = userId
 57→                    else if (word) input.updatedBy = word
 58→                    break
 59→            }
 60→        }
 61→
 62→        return input
 63→    }
 64→
 65→    const {
 66→        data: dictionaries,
 67→        loading,
 68→        error,
 69→        refetch
 70→    } = useDictionariesWithUsers(buildQueryInput(), {
 71→        page: currentPage,
 72→        size: pageSize,
 73→        sort: [{ field: DictionarySortField.CreatedAt, direction: Direction.Desc }]
 74→    })
 75→
 76→    const [createDictionary] = useCreateDictionaryMutation()
 77→    const [updateDictionary] = useUpdateDictionaryMutation()
 78→    const [deleteDictionaries] = useDeleteDictionariesMutation()
 79→
 80→    const pageInfo = dictionaries?.pageInfo
 81→    const totalCount = pageInfo?.totalCount
 82→
 83→    // 검색 조건 변경 핸들러
 84→    const handleSearchChange = (values: DictionarySearchForm) => {
 85→        setSearchConditions(values)
 86→        // 검색 시 첫 페이지로 이동
 87→        setCurrentPage(1)
 88→        // 검색 시 선택 항목 초기화
 89→        setSelectedRowKeys([])
 90→    }
 91→
 92→    // 페이지 변경 핸들러
 93→    const handlePageChange = (page: number, size?: number) => {
 94→        setCurrentPage(page)
 95→        if (size) {
 96→            setPageSize(size)
 97→        }
 98→    }
 99→
100→    // 새 항목 추가 모달 열기
101→    const handleAdd = async () => {
102→        await overlay.openAsync<boolean>(({ isOpen, close }) => (
103→            <DictionaryManageFormModal open={isOpen} onSubmit={handleFormSubmit} onClose={close} />
104→        ))
105→    }
106→
107→    // 편집 모달 열기
108→    const handleEdit = async (record: DictionaryItem) => {
109→        await overlay.openAsync<boolean>(({ isOpen, close }) => (
110→            <DictionaryManageFormModal open={isOpen} onSubmit={handleFormSubmit} onClose={close} item={record} />
111→        ))
112→    }
113→
114→    // 삭제 (단일 또는 대량)
115→    const handleDelete = async (record?: DictionaryItem) => {
116→        let idsToDelete: number[]
117→
118→        if (record) {
119→            idsToDelete = [Number(record.id)]
120→        } else {
121→            if (selectedRowKeys.length === 0) {
122→                message.warning('삭제할 항목을 선택해주세요.')
123→                return
124→            }
125→            idsToDelete = selectedRowKeys.map((key) => Number(key))
126→        }
127→
128→        try {
129→            const result = await deleteDictionaries({
130→                variables: {
131→                    input: {
132→                        ids: idsToDelete
133→                    }
134→                },
135→                context: {
136→                    WHAT: AUDIT_ACTION.DICTIONARY_DELETE
137→                }
138→            })
139→            message.success('삭제되었습니다.')
140→
141→            // 목록 새로고침
142→            await refetch()
143→
144→            if (record) {
145→                // 단일 삭제시 해당 항목만 선택에서 제거
146→                setSelectedRowKeys(selectedRowKeys.filter((key) => key !== record.id))
147→            } else {
148→                // 대량 삭제시 전체 선택 초기화
149→                setSelectedRowKeys([])
150→            }
151→        } catch (error) {
152→            if (error instanceof ApolloError) {
153→                const graphQLError = error.graphQLErrors?.[0]
154→                if (graphQLError) {
155→                    // errorDetail에 따라 커스텀 메시지 표시
156→                    const errorDetail = graphQLError.extensions?.errorDetail
157→                    if (errorDetail === 'AttributesInUse') {
158→                        message.error('속성 또는 속성값에 연결된 용어사전으로 삭제가 불가능합니다.')
159→                        return
160→                    }
161→                }
162→            }
163→            message.error('삭제 중 오류가 발생했습니다.')
164→        }
165→    }
166→
167→    // 폼 제출 핸들러
168→    const handleFormSubmit = async (values: DictionaryFormValues, item?: DictionaryItem): Promise<void> => {
169→        try {
170→            if (item) {
171→                // 수정
172→                await updateDictionary({
173→                    variables: {
174→                        input: {
175→                            id: Number(item.id),
176→                            name: values.name,
177→                            description: values.description,
178→                            updatedAt: getCurrentTime(),
179→                            updatedBy: user?.id ? String(user.id) : '1'
180→                        }
181→                    },
182→                    context: {
183→                        WHAT: AUDIT_ACTION.DICTIONARY_UPDATE
184→                    }
185→                })
186→                message.success('수정되었습니다.')
187→            } else {
188→                // 생성
189→                await createDictionary({
190→                    variables: {
191→                        input: {
192→                            name: values.name,
193→                            description: values.description || '',
194→                            createdAt: getCurrentTime(),
195→                            createdBy: user?.id ? String(user.id) : '1',
196→                            updatedAt: getCurrentTime(),
197→                            updatedBy: user?.id ? String(user.id) : '1'
198→                        }
199→                    },
200→                    context: {
201→                        WHAT: AUDIT_ACTION.DICTIONARY_CREATE
202→                    }
203→                })
204→                message.success('생성되었습니다.')
205→            }
206→            // 선택 항목 초기화
207→            setSelectedItem(undefined)
208→
209→            // 목록 새로고침
210→            await refetch()
211→        } catch (error) {
212→            message.error(item ? '수정 중 오류가 발생했습니다.' : '생성 중 오류가 발생했습니다.')
213→            throw error // 에러를 다시 throw하여 모달이 닫히지 않도록 함
214→        }
215→    }
216→
217→    // 용어명 클릭 핸들러
218→    const handleItemClick = (item: DictionaryItem) => {
219→        setSelectedItem(item)
220→    }
221→
222→    // 상세 패널 닫기 핸들러
223→    const handleCloseDetail = () => {
224→        setSelectedItem(undefined)
225→    }
226→
227→    return {
228→        // 상태
229→        dictionaries,
230→        totalCount,
231→        loading,
232→        selectedRowKeys,
233→        currentPage,
234→        pageSize,
235→        selectedItem,
236→
237→        // 핸들러
238→        handleSearchChange,
239→        handlePageChange,
240→        handleAdd,
241→        handleEdit,
242→        handleDelete,
243→        handleFormSubmit,
244→        setSelectedRowKeys,
245→        handleItemClick,
246→        handleCloseDetail
247→    }
248→}
249→

'use client'

import { DictionaryManagePage } from '@/views/dictionary-manage'

export default function App() {
    return <DictionaryManagePage />
